import type { Decl, Model, TypeExpr } from "./model.js";

/** The text of the header every generated file starts with, unless the config sets another. */
export const DEFAULT_HEADER = "Code generated by strictgen. DO NOT EDIT.";

/** First line of every generated file with the default header. */
export const HEADER = commentHeader(DEFAULT_HEADER);

/** The first line of a generated file: the header text as a `//` comment, for Rust, Go and TypeScript. */
export function commentHeader(text: string): string {
  return `// ${text}`;
}

/**
 * Characters no generated comment holds as themselves: control characters but tab, line and
 * paragraph separators, the byte order mark, bidi controls and lone surrogates. Go rejects NUL
 * and the byte order mark anywhere in a file, Rust rejects a bare carriage return in a doc
 * comment and bidi controls by default, and the rest are hard to see.
 */
const HIDDEN = /[\0-\x08\x0a-\x1f\x7f-\x9f\u061c\u200e\u200f\u2028-\u202e\u2066-\u2069\ufeff]|[\ud800-\udfff]/gu;

/** Text for a generated comment, in any language: each {@link HIDDEN} character as `\u{...}`. */
export function commentText(text: string): string {
  return text.replace(HIDDEN, (c) => `\\u{${(c.codePointAt(0) ?? 0).toString(16)}}`);
}

/** Compares by UTF-16 code units, so the order never depends on the locale. */
export function compare(a: string, b: string): number {
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

/** One file an emitter writes, with a name relative to the folder its target owns. */
export interface EmittedFile {
  readonly name: string;
  readonly contents: string;
}

/** The declarations of each schema file, schemas sorted by name and declarations kept in model order. */
export function bySchema(model: Model): Map<string, Decl[]> {
  const groups = new Map<string, Decl[]>();
  for (const schema of [...new Set(model.decls.map((d) => d.schema))].sort(compare)) {
    groups.set(schema, []);
  }
  for (const decl of model.decls) groups.get(decl.schema)?.push(decl);
  return groups;
}

/** Names of the declarations a type refers to. */
export function typeRefs(type: TypeExpr): string[] {
  switch (type.kind) {
    case "ref":
      return [type.name];
    case "array":
      return typeRefs(type.items);
    case "map":
      return [...typeRefs(type.key), ...typeRefs(type.value)];
    default:
      return [];
  }
}

/** Every type a declaration uses: field, variant, alias and map types. */
export function declTypes(decl: Decl): TypeExpr[] {
  switch (decl.kind) {
    case "struct":
      return [
        ...decl.fields.map((f) => f.type),
        ...(decl.rest === undefined ? [] : [decl.rest.key, decl.rest.value]),
      ];
    case "tagged":
      return decl.variants.map((v) => ({ kind: "ref", name: v.type }));
    case "untagged":
      return decl.variants.map((v) => v.type);
    case "alias":
      return [decl.type];
    case "enum":
    case "id":
      return [];
  }
}

/**
 * The declarations of other schema files that `decls` refer to, grouped by
 * schema and sorted, for imports between generated files. `typesOf` picks the
 * types an emitter writes for a declaration.
 */
export function imports(
  model: Model,
  decls: readonly Decl[],
  typesOf: (decl: Decl) => TypeExpr[] = declTypes,
): Map<string, string[]> {
  const owner = new Map(model.decls.map((d) => [d.name, d.schema]));
  const names = new Set(decls.flatMap((d) => typesOf(d).flatMap(typeRefs)));
  const own = decls[0]?.schema;
  const out = new Map<string, string[]>();
  for (const name of [...names].sort(compare)) {
    const schema = owner.get(name);
    if (schema === undefined || schema === own) continue;
    out.set(schema, [...(out.get(schema) ?? []), name]);
  }
  return new Map([...out].sort(([a], [b]) => compare(a, b)));
}
